export async function fillDraft(bytes,d,lib,addressConfirmed,options={}){
 const pdf=await lib.PDFDocument.load(bytes),font=await pdf.embedFont(lib.StandardFonts.Helvetica),pages=pdf.getPages();
 const clean=s=>String(s??'').toUpperCase().replace(/\s+/g,' ').trim();
 function text(p,s,x,y,size=11){s=clean(s);if(!s)return;if(/[^\x20-\x7e]/.test(s))throw Error('Use English / Latin spellings in the form.');pages[p].drawText(s,{x,y:pages[p].getHeight()-y,size,font});}
 function box(p,s,x,top,cols=25,rows=1,gap=22.3,label='A field'){s=clean(s);if(!s)return;if(s.length>cols*rows)throw Error(`${label} is too long for its ${cols*rows} character boxes. Review the wording without losing required information.`);[...s].forEach((c,i)=>text(p,c,x+(i%cols)*17+(17-font.widthOfTextAtSize(c,11))/2,top+14.2+Math.floor(i/cols)*gap));}
 function line(p,s,x,baseline,width,size=10,label='A field'){s=clean(s);if(!s)return;while(font.widthOfTextAtSize(s,size)>width&&size>7)size-=.25;if(font.widthOfTextAtSize(s,size)>width)throw Error(label+' is too long for the space in the form.');text(p,s,x,baseline,size);}
 function multiline(p,s,x,baseline,width,maxLines,gap=15,label='Details'){s=clean(s);if(!s)return;const words=s.split(' '),lines=[];let current='';for(const word of words){if(font.widthOfTextAtSize(word,9)>width)throw Error(label+': a word is too long for the form.');if(font.widthOfTextAtSize((current+' '+word).trim(),9)>width){lines.push(current);current=word;}else current=(current+' '+word).trim();}if(current)lines.push(current);if(lines.length>maxLines)throw Error(label+' exceed the available space. Shorten the wording or prepare an additional sheet.');lines.forEach((v,i)=>text(p,v,x,baseline+i*gap,9));}
 function tick(p,x,top){text(p,'X',x+2,top+8.7,10);}
 function choice(p,v,map,top){if(v&&map[v]!==undefined)tick(p,map[v],top);}
 function date(p,s,xs,top){if(!s)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('Check all date fields.');const [y,m,day]=s.split('-');[...(day+m+y)].forEach((c,i)=>text(p,c,xs[i]+5,top+14.2));}
 box(0,[d.given,d.surname].filter(Boolean).join(' '),139.95,177.3,25,2,22.3,'Applicant name');box(0,d.alias,140.1,227.9,25,2,21.9,'Alias');
 date(0,d.dob,[112.2,129,159.65,176.45,208.65,225.4,242.2,258.95],283.4);choice(0,d.sex,{Male:347,Female:398.5},290);
 choice(0,d.marital,{Single:104.8,Married:157,Separated:213.4,Divorced:277.4,Widowed:336.2,Cohabited:398.5,Customary:465.5},325.2);
 if(d.spouseType==='Singapore Citizen'){tick(0,159.4,357.6);box(0,d.spouseNric,370.85,351.7,9,1,22.3,'Spouse NRIC');}else if(d.spouseType==='Singapore Permanent Resident'){tick(0,159.6,377);box(0,d.spouseNric,371.25,376.5,9,1,22.3,'Spouse NRIC');}else if(d.spouseType==='Others'){tick(0,159.8,399.6);line(0,d.spouseNationality,283,415,268,10,'Spouse nationality');}
 box(0,d.birthplace,141.65,430,25,1,22.3,'Place of birth');box(0,d.birthstate,141.5,455.3,25,1,22.3,'State of birth');box(0,d.race,140.9,480.9,25,1,22.3,'Race');box(0,d.nationality,140.7,506,25,1,22.3,'Nationality');
 const documents={'International Passport':[197.1,558.3],'Diplomatic Passport':[316.3,558.3],'Official Passport':[426.2,558.3],'Service Passport':[197,571.4],'Document of Identity':[316.2,571.3],'Certificate of Identity':[426.5,571.3],Others:[197.1,584.9]};if(documents[d.documentType])tick(0,...documents[d.documentType]);if(d.documentType==='Others')line(0,d.documentOther,312,595,248,10,'Travel document type');
 box(0,d.passport,139.15,609.6,15,1,22.3,'Travel document number');date(0,d.issued,[139.35,156.4,188.35,205.4,237.25,254.3,271.3,288.35],642.3);date(0,d.expiry,[395.3,412.35,444.05,461.1,493.35,510.4,527.4,544.45],642.9);box(0,d.issuecountry,139.95,682.8,25,1,22.3,'Place of issue');box(0,d.prcId,141.6,733,18,1,22.3,'PRC ID');
 if(addressConfirmed){box(1,d.rescountry,141.15,70.5,25,1,22.3,'Country of residence');box(1,d.resstate,141.15,104.5,25,1,22.3,'State of residence');box(1,d.prefecture,140.65,138,25,1,22.3,'Prefecture');box(1,d.district,141.15,168.5,25,1,22.3,'District');line(1,d.address,75,216,490,10,'Residential address');}
 // Long email addresses use the full width, keeping every character intact.
 if(clean(d.email).length>25)line(1,d.email,143,274.2,418,10,'Email address');else box(1,d.email,139.9,260,25,1,22.3,'Email address');box(1,d.phone,139.75,286,25,1,22.3,'Contact number');box(1,d.occupation,139.95,313,25,1,22.3,'Occupation');
 const edu={'No Formal Education':[142.3,345.2],Primary:[258.1,344.8],Secondary:[318.6,344.8],'Pre-University':[390.4,345.1],Diploma:[142.3,366.9],University:[207.9,366.4],'Post-Graduate':[287,366.9]};if(edu[d.education])tick(1,...edu[d.education]);box(1,d.income,142.6,398,11,1,22.3,'Annual income');box(1,d.religion,142.15,428,25,1,22.3,'Religion');date(1,d.arrival,[200.75,217.8,249.75,266.8,298.65,315.7,332.7,349.75],456);
 choice(1,d.visaType,{'Single Journey':95.9,'Double Journey':184.9,'Triple Journey':275,'Multiple Journey':364.4},503);choice(1,d.purpose,{Social:137.6,Business:210.4},525.3);line(1,d.purposeDetails,115,568,425,10,'Purpose details');choice(1,d.stay,{'Less than 30 days':240.1,'More than 30 days':353.1},587.4);if(d.stay==='More than 30 days')multiline(1,d.longStay,35,649,530,2,18,'Long-stay explanation');
 choice(2,d.accommodation,{"Next of Kin’s Place":24.1,"Relative’s Place":121.8,"Friend’s Place":213,Hotel:300.6,Others:348.4},89.7);if(d.accommodation==='Others')line(2,d.accommodationOther,470,99,94,9,'Accommodation type');box(2,d.block,29.55,128,5,1,22.3,'Block / house number');box(2,d.floor,159.15,128,2,1,22.3,'Floor');box(2,d.unit,245.55,128,4,1,22.3,'Unit');box(2,d.postal,360.75,128,6,1,22.3,'Postal code');box(2,d.street,97.55,153,20,1,22.3,'Singapore street name');line(2,d.hotelPhone,502,164,68,8,'Hotel contact number');line(2,d.building,100,196,464,10,'Building name');choice(2,d.resided,{Yes:58.8,No:111.7},243.5);
 if(d.resided==='Yes'){for(const [i,r]of (options.residences||[]).entries()){if(i>=4)throw Error('More than four residence entries need an additional sheet.');const y=313+i*27;line(2,r.country,31,y,100,8,'Residence country');multiline(2,r.address,139,y,309,2,10,'Residence address');const format=s=>s?s.split('-').reverse().join('/'):'';line(2,format(r.from),458,y,57,8,'Residence start date');line(2,format(r.to),522,y,56,8,'Residence end date');}}
 box(2,d.companionRelation,139,481,25,1,22.3,'Companion relationship');box(2,d.companionName,139.15,538,25,2,20,'Companion name');date(2,d.companionDob,[141.9,158.7,189.35,206.15,238.35,255.1,271.9,288.65],593);choice(2,d.companionSex,{Male:371.1,Female:423.9},595.5);box(2,d.companionNationality,139.65,635,25,1,22.3,'Companion nationality');box(2,d.companionPassport,140.35,663,15,1,22.3,'Companion document number');
 box(3,d.localName,139.7,74,25,2,20,'Local contact / hotel name');box(3,d.localRelation,139.7,133,25,1,22.3,'Local contact relationship');line(3,d.localPhone,92,192,113,10,'Local phone');line(3,d.localEmail,322,192,214,9,'Local email');
 ['entryRefused','convicted','prohibited','differentPassport'].forEach((k,i)=>choice(3,d[k],{Yes:469.2,No:514.9},[254.5,272.6,290.1,306.8][i]));multiline(3,d.antecedentDetails,29,355,536,3,15,'Antecedent details');if(d.declarationDate)line(3,d.declarationDate.split('-').reverse().join('/'),87,783,73,10,'Declaration date');
 return await pdf.save();
}
